import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Dict, Any, Sequence

def _define_hyperparameters():
    """Define hyperparameter values for the model."""
    return {
        'learning_rate': 0.001,
        'hidden_dim': 512,
        'dropout_rate': 0.2,
        'num_blocks': 4,
        'branch_filters': 32 # Filters per branch, total filters = 32 * 3 = 96
    }

class InceptionBlock(nn.Module):
    """An Inception-style block with multiple parallel convolutions."""
    branch_filters: int

    @nn.compact
    def __call__(self, x):
        # Branch 1: kernel size 3
        branch1 = nn.Conv(features=self.branch_filters, kernel_size=(3,), padding='SAME')(x)

        # Branch 2: kernel size 5
        branch2 = nn.Conv(features=self.branch_filters, kernel_size=(5,), padding='SAME')(x)

        # Branch 3: kernel size 7
        branch3 = nn.Conv(features=self.branch_filters, kernel_size=(7,), padding='SAME')(x)

        # Concatenate features from all branches
        concatenated = jnp.concatenate([branch1, branch2, branch3], axis=-1)

        # Use a 1x1 convolution to mix features and match dimension for residual connection
        bottleneck = nn.Conv(features=x.shape[-1], kernel_size=(1,))(concatenated)

        return nn.relu(x + bottleneck)

class MultiScaleCNN(nn.Module):
    """A CNN using Inception-style blocks to capture features at multiple scales."""
    d_output: int
    task_type: str
    num_blocks: int
    branch_filters: int
    hidden_dim: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Initial convolution to set the feature depth
        initial_filters = self.branch_filters * 3
        x = nn.Conv(features=initial_filters, kernel_size=(7,), padding='SAME')(x)
        x = nn.relu(x)

        # Stack of Inception Blocks
        for _ in range(self.num_blocks):
            x = InceptionBlock(branch_filters=self.branch_filters)(x)

        # Global average pooling
        x = jnp.mean(x, axis=1)

        # MLP head
        x = nn.Dense(features=self.hidden_dim)(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class NetworkWrapper:
    def __init__(self, **kwargs):
        self.network = MultiScaleCNN(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    return NetworkWrapper(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        num_blocks=hparams.get("num_blocks"),
        branch_filters=hparams.get("branch_filters"),
        hidden_dim=hparams.get("hidden_dim"),
        dropout_rate=hparams.get("dropout_rate")
    )
